import{_ as s,y as i,a as r,o as a,a2 as e,D as n}from"./chunks/framework.DCcmcJcL.js";const m=JSON.parse('{"title":"Customer Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configure/settings.md","filePath":"configure/settings.md","lastUpdated":1789441803000}'),l={name:"configure/settings.md"};function c(g,t,h,u,d,p){const o=i("ImagePopup");return a(),r("div",null,[t[0]||(t[0]=e('<h1 id="customer-settings" tabindex="-1">Customer Settings <a class="header-anchor" href="#customer-settings" aria-label="Permalink to &quot;Customer Settings&quot;">​</a></h1><p>The <strong>Settings</strong> screen of the <strong>Customer</strong> group decides how customer accounts are created and signed in to, which social accounts customers can sign in with, and whether the wishlist and the newsletter are offered. What customers see on the storefront is described in <a href="./../customer/customer-account.html">Customer Account</a>.</p><h2 id="create-new-account-options" tabindex="-1">Create new account options <a class="header-anchor" href="#create-new-account-options" aria-label="Permalink to &quot;Create new account options&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Customer &gt;&gt; Settings</strong>.</li><li>In <strong>Create New Account Options</strong>, choose the <strong>Default Group</strong> for customers who create an account with the storefront&#39;s sign-up form: <strong>General</strong> (the default), <strong>Guest</strong> or <strong>Wholesale</strong>.</li><li>Switch <strong>Allow NewsLetter</strong> on or off. While it&#39;s on, the sign-up form shows a <strong>Subscribe to newsletter</strong> checkbox. It is on by default.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),n(o,{src:"/images/configure/customer-settings.png",alt:"Create New Account Options, Email Verification and Login Options sections of the Customer Settings screen"}),t[1]||(t[1]=e('<p>Both settings apply to every channel. Customer groups are described in <a href="./../customer/customer-group.html">Customer Groups</a>, and the sign-up form in <a href="./../customer/customer-account.html#sign-up">Customer Account</a>.</p><h2 id="email-verification" tabindex="-1">Email verification <a class="header-anchor" href="#email-verification" aria-label="Permalink to &quot;Email verification&quot;">​</a></h2><p>While <strong>Allow Email Verification</strong> is on, a new customer receives an email with a verification link and can&#39;t sign in until they open it. Until then, signing in shows <em>Verify your email account first.</em> It is off by default and applies to every channel.</p><ol><li>Go to <strong>Configure &gt;&gt; Customer &gt;&gt; Settings</strong>.</li><li>In <strong>Email Verification</strong>, switch <strong>Allow Email Verification</strong> on or off.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>With verification on, the welcome email set under <a href="./notifications.html">Notifications</a> is sent after the customer verifies their address, instead of straight after they sign up.</p><h2 id="login-options" tabindex="-1">Login options <a class="header-anchor" href="#login-options" aria-label="Permalink to &quot;Login options&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Customer &gt;&gt; Settings</strong>.</li><li>In <strong>Login Options</strong>, choose where <strong>Redirect Customer to the selected page</strong> sends customers after they sign in: <strong>Home</strong> (the default) or <strong>Account</strong>, their account profile.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>A customer who was asked to sign in on the way to another page returns to that page instead. Signing in is described in <a href="./../customer/customer-account.html#sign-in">Customer Account</a>.</p><h2 id="social-login" tabindex="-1">Social login <a class="header-anchor" href="#social-login" aria-label="Permalink to &quot;Social login&quot;">​</a></h2><p>Social login lets customers sign in with their Facebook, X (Twitter), Google, LinkedIn or GitHub account. The button of each provider you switch on appears under the storefront&#39;s sign-in and sign-up forms. The first time a customer signs in with a provider, the store creates their account, or links it to an existing account with the same email address. It then opens their account profile, or the page they were on when they were asked to sign in.</p><p>Before you start, create an app in the developer console of each provider you want to offer, and copy its client ID and client secret.</p><ol><li>Go to <strong>Configure &gt;&gt; Customer &gt;&gt; Settings</strong>.</li><li>In <strong>Social Login</strong>, switch on the provider, such as <strong>Enable Google</strong>. Its <strong>Client ID</strong>, <strong>Client Secret</strong> and <strong>Redirect URL</strong> appear.</li><li>Enter the <strong>Client ID</strong> and <strong>Client Secret</strong> of your app.</li><li>Check the <strong>Redirect URL</strong>. Keep the path and change only the domain to your storefront&#39;s, such as <code>https://www.example.com/customer/social-login/google/callback</code>.</li><li>Add the same <strong>Redirect URL</strong> to your app in the provider&#39;s developer console.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',12)),n(o,{src:"/images/configure/customer-social-login.png",alt:"Social Login section with Google switched on and its client ID, client secret and redirect URL fields"}),t[2]||(t[2]=e('<p>Each provider has these four settings:</p><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enable Facebook</strong>, <strong>Enable X (Twitter)</strong>, <strong>Enable Google</strong>, <strong>Enable LinkedIn</strong>, <strong>Enable GitHub</strong></td><td>Shows the provider&#39;s button on the sign-in and sign-up forms. Saved per channel, so choose the channel at the top of the screen first when your store has more than one.</td></tr><tr><td><strong>Client ID</strong></td><td>The identifier of your app in the provider&#39;s developer console. Applies to every channel.</td></tr><tr><td><strong>Client Secret</strong></td><td>The secret of that app. Keep it private. Applies to every channel.</td></tr><tr><td><strong>Redirect URL</strong></td><td>Where the provider sends the customer back after they sign in. It must match the URL saved in your app exactly. Applies to every channel.</td></tr></tbody></table><p>The <strong>Redirect URL</strong> path is different for each provider:</p><ul><li><strong>Facebook</strong>: <code>/customer/social-login/facebook/callback</code></li><li><strong>X (Twitter)</strong>: <code>/customer/social-login/twitter/callback</code></li><li><strong>Google</strong>: <code>/customer/social-login/google/callback</code></li><li><strong>LinkedIn</strong>: <code>/customer/social-login/linkedin-openid/callback</code></li><li><strong>GitHub</strong>: <code>/customer/social-login/github/callback</code></li></ul>',4)),n(o,{src:"/images/configure/customer-social-login-storefront.png",alt:"Facebook, X, Google, LinkedIn and GitHub buttons under the storefront sign-in form"}),t[3]||(t[3]=e('<h3 id="a-new-store-shows-all-five-buttons" tabindex="-1">A new store shows all five buttons <a class="header-anchor" href="#a-new-store-shows-all-five-buttons" aria-label="Permalink to &quot;A new store shows all five buttons&quot;">​</a></h3><p>A new installation switches on all five providers for the default channel. Their buttons appear on the storefront before you enter any keys, and signing in with them fails until you do, so switch off the providers you don&#39;t offer.</p><h2 id="wishlist" tabindex="-1">Wishlist <a class="header-anchor" href="#wishlist" aria-label="Permalink to &quot;Wishlist&quot;">​</a></h2><p><strong>Allow Wishlist option</strong> lets shoppers save products to a wishlist. While it&#39;s off, the wishlist buttons on product cards and product pages, the wishlist icon in the header and the <strong>Wishlist</strong> page of the customer account are hidden. It is on by default and applies to every channel.</p><ol><li>Go to <strong>Configure &gt;&gt; Customer &gt;&gt; Settings</strong>.</li><li>In <strong>Wishlist</strong>, switch <strong>Allow Wishlist option</strong> on or off.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),n(o,{src:"/images/configure/customer-wishlist-newsletter.png",alt:"Wishlist and Newsletter Subscription sections of the Customer Settings screen"}),t[4]||(t[4]=e('<p>The customer&#39;s wishlist page is described in <a href="./../customer/customer-account.html#wishlist">Customer Account</a>.</p><h2 id="newsletter-subscription" tabindex="-1">Newsletter subscription <a class="header-anchor" href="#newsletter-subscription" aria-label="Permalink to &quot;Newsletter subscription&quot;">​</a></h2><p><strong>Allow Newsletter Subscription</strong> shows the newsletter subscription form in the storefront footer. It is on by default and applies to every channel. The checkbox on the sign-up form is set separately, by <strong>Allow NewsLetter</strong> under <strong>Create New Account Options</strong>.</p><ol><li>Go to <strong>Configure &gt;&gt; Customer &gt;&gt; Settings</strong>.</li><li>In <strong>Newsletter Subscription</strong>, switch <strong>Allow Newsletter Subscription</strong> on or off.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The customers who subscribe are listed under <a href="./../marketing/newsletter-subscription.html">Newsletter Subscriptions</a>.</p>',5))])}const w=s(l,[["render",c]]);export{m as __pageData,w as default};
